/* SINGLE SOURCE OF TRUTH for every metric. Nothing is computed inline in a component. */
import type { Fmt } from './formats';
import { maxOf, minOf } from './stats';

export type TableName = 'visits' | 'sessions' | 'checkins' | 'sales' | 'newc' | 'lapsed' | 'payroll' | 'leads' | 'bookings';
export type Domain = 'attendance' | 'revenue' | 'growth' | 'people' | 'risk';
export type Aggregation = 'sum' | 'weighted' | 'avg' | 'median' | 'count' | 'distinct' | 'custom';

export interface QueryContext {
  ratePerSession: number;            // user-editable assumption (₹/session)
  todayTs: number;
  /* Operator-editable thresholds. Metrics read these so a KPI card and the insight beside it
     can never disagree about what "dormant" or "high risk" means. */
  dormantDays: number;
  riskHigh: number;
  zeroUsageDays: number;
  matureDays: number;                // a first-timer needs this long before "never returned" is fair
  medianFirstMembership: number;     // fallback value for pipeline and conversion-value estimates
  durationDefaultMin: number;        // 55 — labelled estimate while Duration is corrupted
  durationSuspect: boolean;
  slotFill?: Map<string, number>;    // slot-key → studio fill rate (for draw premium)
  suspect?: Set<string>;             // metric ids whose inputs failed a health check
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type R = any;

export interface MetricDef {
  id: string;
  label: string;
  description: string;
  domain: Domain;
  format: Fmt;
  table: TableName;
  formula: string;                   // documentation shown in the ⓘ panel
  aggregation: Aggregation;
  higherIsBetter: boolean;
  target?: number;
  minSample: number;
  sources: string[];
  num?: (r: R, ctx: QueryContext) => number | boolean | null;
  den?: (r: R, ctx: QueryContext) => number | null;
  distinctKey?: (r: R) => string | null;
  custom?: (rows: R[], ctx: QueryContext) => number | null;
  /** Reason the metric is suspect right now (adds ⚠). */
  suspect?: (ctx: QueryContext) => string | null;
  /** True when a row failing to contribute means a DATA GAP rather than an intentional filter.
      `utilisation` needs a session cap that 88% of rows lack — that is a gap worth disclosing.
      `revenue_at_risk_30d` only counts memberships expiring soon — low coverage is the definition,
      not a defect, so it stays false. Only opt-in metrics raise the coverage warning. */
  coverageMatters?: boolean;
  /** Plain-language explanation of what the uncovered rows are. */
  coverageReason?: string;
}

export interface MetricResult {
  value: number | null;
  n: number;                 // rows in scope
  contributing: number;      // rows that actually had the inputs this metric needs
  coverage: number | null;   // contributing / n — null when n is 0
  suspect: string | null;
}

const b2n = (v: number | boolean | null | undefined): number | null => (v === null || v === undefined ? null : typeof v === 'boolean' ? (v ? 1 : 0) : v);

export function computeMetric(def: MetricDef, rows: R[], ctx: QueryContext): MetricResult {
  const suspect = def.suspect?.(ctx) ?? (ctx.suspect?.has(def.id) ? 'An upstream health check failed for this metric.' : null);
  const n = rows.length;
  const done = (value: number | null, contributing: number): MetricResult =>
    ({ value, n, contributing, coverage: n ? contributing / n : null, suspect });

  if (def.aggregation === 'custom') return done(def.custom!(rows, ctx), n);
  if (def.aggregation === 'distinct') {
    const s = new Set<string>();
    let c = 0;
    for (const r of rows) { const k = def.distinctKey!(r); if (k !== null) { s.add(k); c++; } }
    return done(s.size, c);
  }
  if (def.aggregation === 'count') {
    let hits = 0;
    for (const r of rows) if (def.num!(r, ctx)) hits++;
    return done(hits, n);               // a filter-count can evaluate every row
  }
  if (def.aggregation === 'sum') {
    let s = 0; let c = 0;
    for (const r of rows) { const v = b2n(def.num!(r, ctx)); if (v !== null) { s += v; c++; } }
    return done(c ? s : null, c);
  }
  if (def.aggregation === 'weighted') {
    let ns = 0; let ds = 0; let c = 0;
    for (const r of rows) {
      const d = def.den!(r, ctx); if (d === null || d === undefined) continue;
      const v = b2n(def.num!(r, ctx)); if (v === null) continue;
      ns += v; ds += d; c++;
    }
    return done(ds > 0 ? ns / ds : null, c);
  }
  // avg / median over non-null values
  const vals: number[] = [];
  for (const r of rows) { const v = b2n(def.num!(r, ctx)); if (v !== null) vals.push(v); }
  if (!vals.length) return done(null, 0);
  if (def.aggregation === 'avg') return done(vals.reduce((a, b) => a + b, 0) / vals.length, vals.length);
  vals.sort((a, b) => a - b);
  const mid = Math.floor(vals.length / 2);
  return done(vals.length % 2 ? vals[mid] : (vals[mid - 1] + vals[mid]) / 2, vals.length);
}

/** Human explanation when a metric describes only part of the scope. */
export function coverageNote(def: MetricDef, r: MetricResult): string | null {
  if (!def.coverageMatters || r.coverage === null || r.coverage >= 0.9 || r.n === 0) return null;
  return `Measured on ${r.contributing.toLocaleString('en-IN')} of ${r.n.toLocaleString('en-IN')} rows in scope (${(r.coverage * 100).toFixed(1)}%). ${def.coverageReason ?? 'The remaining rows do not carry the columns this metric needs.'}`;
}

/* ---------- helpers ---------- */
const durationH = (r: R, ctx: QueryContext) => ((r.duration_min ?? ctx.durationDefaultMin) / 60);
const durSuspect = (ctx: QueryContext) => (ctx.durationSuspect ? 'Duration (Minutes) is corrupted in Checkins; hours use a 55-minute estimate.' : null);
const stddevOverMean = (vals: number[]) => {
  if (vals.length < 2) return null;
  const m = vals.reduce((a, b) => a + b, 0) / vals.length;
  if (!m) return null;
  const v = vals.reduce((a, b) => a + (b - m) ** 2, 0) / (vals.length - 1);
  return Math.sqrt(v) / m;
};
const sumOf = (rows: R[], f: (r: R) => number | null) => { let s = 0; let any = false; for (const r of rows) { const v = f(r); if (v !== null && v !== undefined) { s += v; any = true; } } return any ? s : null; };
/** Sale-level payment fields repeat on line items. Count each sale once for business totals. */
const distinctSaleSum = (rows: R[], f: (r: R) => number | null) => {
  const bySale = new Map<string, number>(); let i = 0;
  for (const r of rows) { if (r.voided) continue; const v = f(r); if (v === null || v === undefined) continue; const key = r.sale_id ?? r.sale_item_id ?? `row:${i++}`; bySale.set(key, Math.max(bySale.get(key) ?? Number.NEGATIVE_INFINITY, v)); }
  return bySale.size ? [...bySale.values()].reduce((a, b) => a + b, 0) : null;
};
const sessionRevPac = (rows: R[]) => { const rev = sumOf(rows, (r) => r.revenue); const att = sumOf(rows, (r) => r.checked_in); return rev !== null && att ? rev / att : null; };
const slotKey = (r: R) => `${r.location}|${r.day}|${r.time}|${r.format}`;

const S = (table: TableName, cols: string[]) => cols.map((c) => `${table === 'newc' ? 'New' : table[0].toUpperCase() + table.slice(1)}.${c}`);

