export const METRICS: Record<string, MetricDef> = Object.fromEntries(defs.map((d) => [d.id, d]));
export const METRIC_LIST = defs;
export const metric = (id: string): MetricDef => {
  const d = METRICS[id];
  if (!d) throw new Error(`Unknown metric: ${id}`);
  return d;
};
